    await assert.rejects(postHealthStockReceipt(context, { ...input, donorName: "" }), /doador/);
    const receipt = await postHealthStockReceipt(context, input);
    assert.equal(receipt.status, "PENDING_APPROVAL"); assert.equal(await countRows(database, t.materialStocks), 0); assert.equal(await countRows(database, t.materialMovements), 0);
    assert.equal((await postHealthStockReceipt(context, input)).id, receipt.id);
    await assert.rejects(postHealthStockReceipt(context, { ...input, items: [{ ...input.items[0], quantity: 6 }] }), /outros dados/);
    await Promise.all([approveHealthStockReceipt(context, receipt.id), approveHealthStockReceipt(context, receipt.id)]);
    assert.equal((await one(database.select().from(t.materialStocks).limit(1))).quantity, 5); assert.equal(await countRows(database, t.materialMovements), 1);
    const approved = await one(database.select().from(t.checklistReceiptApprovals).where(eq(t.checklistReceiptApprovals.id, receipt.id)).limit(1));
    assert.equal(approved.approvedByUsuarioId, context.user.id); assert.ok(approved.approvedAt);
    await assert.rejects(approveHealthStockReceipt({ ...context, user: { ...context.user, profileCode: "HEALTH_OPERATOR", hasHealthAccessScope: true, allowedHealthUnitIds: ["health-u2"] } }, receipt.id), /acesso|unidade/i);
    await database.insert(t.people).values({ id: "health-person", fullName: "Cidadão", cpf: "12345678909", status: "Ativo" });
    await database.insert(t.patients).values({ id: "health-patient", personId: "health-person", cns: "111111111111111", referenceUnitId: "health-u1", status: "Ativo" });
    await database.insert(t.suppliers).values({ id: "other-health-provider", status: "Ativo" });
    stage = "cotas, autorização e agendamento";
    await database.insert(t.healthRegulationQuotas).values([{ id: "quota-one", providerSupplierId: "fornecedor", unitId: "health-u1", period: "2026-10", totalQuantity: 2 }, { id: "quota-two", providerSupplierId: "other-health-provider", unitId: "health-u1", period: "2026-10", totalQuantity: 2 }, { id: "quota-wrong", providerSupplierId: "fornecedor", unitId: "health-u2", period: "2026-10", totalQuantity: 2 }]);
    await database.insert(t.healthRegulationRequests).values(["reg-one", "reg-two"].map(id => ({ id, patientId: "health-patient", requestUnitId: "health-u1", createdByUsuarioId: context.user.id })));
    await assert.rejects(transitionRegulationRequest(context, "reg-one", "AUTORIZADA", { quotaId: "quota-wrong" }), /corresponder/);
    const authorization = await transitionRegulationRequest(context, "reg-one", "AUTORIZADA", { quotaId: "quota-one" });
    assert.equal((await transitionRegulationRequest(context, "reg-one", "AUTORIZADA", { quotaId: "quota-one" })).guideNumber, authorization.guideNumber);
    await transitionRegulationRequest(context, "reg-two", "AUTORIZADA", { quotaId: "quota-one" });
    assert.equal((await one(database.select().from(t.healthRegulationQuotas).where(eq(t.healthRegulationQuotas.id, "quota-one")).limit(1))).reservedQuantity, 2);
    await assert.rejects(saveRegulationQuota(context, { providerSupplierId: "fornecedor", unitId: "health-u1", period: "2026-10", totalQuantity: 1 }), /menor/);
    await transitionRegulationRequest(context, "reg-two", "AGENDADA", { scheduledAt: "2026-10-20T10:00:00Z" });
    await transitionRegulationRequest(context, "reg-two", "CANCELADA");
    assert.equal((await one(database.select().from(t.healthRegulationQuotas).where(eq(t.healthRegulationQuotas.id, "quota-one")).limit(1))).reservedQuantity, 1);
    await transferAuthorization(context, "reg-one", "quota-two"); await transferAuthorization(context, "reg-one", "quota-two");
    await transitionRegulationRequest(context, "reg-one", "EXECUTADA"); await transitionRegulationRequest(context, "reg-one", "EXECUTADA");
    const quota = await one(database.select().from(t.healthRegulationQuotas).where(eq(t.healthRegulationQuotas.id, "quota-two")).limit(1));
    assert.equal(quota.reservedQuantity, 0); assert.equal(quota.realizedQuantity, 1);
    const executionAt = (await one(database.select().from(t.healthRegulationRequests).where(eq(t.healthRegulationRequests.id, "reg-one")).limit(1))).executedAt;
    await transitionRegulationRequest(context, "reg-one", "DEVOLVIDA"); await transitionRegulationRequest(context, "reg-one", "RECEBIDA");
    await transitionRegulationRequest(context, "reg-one", "AUTORIZADA", { quotaId: "quota-two" }); await transitionRegulationRequest(context, "reg-one", "EXECUTADA");
    assert.equal((await one(database.select().from(t.healthRegulationQuotas).where(eq(t.healthRegulationQuotas.id, "quota-two")).limit(1))).realizedQuantity, 1);
    assert.equal((await one(database.select().from(t.healthRegulationRequests).where(eq(t.healthRegulationRequests.id, "reg-one")).limit(1))).executedAt?.valueOf(), executionAt?.valueOf());
    await database.insert(t.healthProfessionals).values({ id: "health-professional", employeeId: "servidora-ana", unitId: "health-u1", isActive: true });
    stage = "conclusão e observação";
    await database.insert(t.medicalRecords).values({ id: "health-record", patientId: "health-patient", professionalId: "health-professional", unitId: "health-u1" });
    await concludeHealthCare(context, { medicalRecordId: "health-record", outcome: "Observação", conduct: "Acompanhamento clínico registrado." });
    const observation = await one(database.select().from(t.healthObservations).where(eq(t.healthObservations.medicalRecordId, "health-record")).limit(1));
    await addClinicalEvolution(context, { medicalRecordId: "health-record", content: "Evolução durante o episódio de observação." });
    assert.equal(await countRows(database, t.healthClinicalEvolutions, eq(t.healthClinicalEvolutions.medicalRecordId, "health-record")), 1);
    await assert.rejects(saveMedicalRecordNarrative(context, { medicalRecordId: "health-record", anamnesis: "Alteração", assessment: null, evolution: null, conduct: null, observations: null }), /somente para consulta/);
    await transitionObservation(context, observation.id, "Em observação");
    assert.equal((await one(database.select().from(t.healthObservations).where(eq(t.healthObservations.id, observation.id)).limit(1))).dischargedAt, null);
    await transitionObservation(context, observation.id, "Alta");
    await assert.rejects(addClinicalEvolution(context, { medicalRecordId: "health-record", content: "Evolução após alta." }), /somente para consulta/);

    await database.insert(t.medicalRecords).values(["prenatal-one", "prenatal-two", "postpartum", "care-other"].map((id, index) => ({ id, patientId: "health-patient", professionalId: "health-professional", unitId: "health-u1", date: new Date(index === 0 ? "2026-01-01T12:00:00Z" : index === 1 ? "2026-02-01T12:00:00Z" : "2026-05-01T12:00:00Z") })));
    const pregnancyInput = { medicalRecordId: "prenatal-one", calculationMethod: "LMP", lastMenstrualDate: "2025-11-01", ultrasoundDate: null, ultrasoundGestationalDays: null, baselineWeight: 60, height: 1.6, pregnancyType: "SINGLE", previousPregnancies: 0, lastScreeningDate: null };
    stage = "gestação e pré-natal";
    const pregnancy = await openPregnancy(context, pregnancyInput);
    assert.equal(pregnancy.estimatedDeliveryDate.toISOString().slice(0, 10), "2026-08-08");
    await assert.rejects(openPregnancy(context, pregnancyInput), /gestação ativa/);
    const prenatalOne = await recordPrenatalVisit(context, { medicalRecordId: "prenatal-one", pregnancyId: pregnancy.id, weight: 61, bloodPressure: "120/80", notes: "Evolução do primeiro trimestre" });
    const prenatalTwo = await recordPrenatalVisit(context, { medicalRecordId: "prenatal-two", pregnancyId: pregnancy.id, weight: 63, bloodPressure: "120/80", notes: "Evolução do primeiro trimestre" });
    assert.equal(prenatalOne.gestationalDays, 61); assert.equal(prenatalTwo.gestationalDays, 92); assert.equal(prenatalOne.bmi, 23.83);
    await assert.rejects(recordPrenatalVisit(context, { medicalRecordId: "prenatal-one", pregnancyId: pregnancy.id, weight: 62, bloodPressure: null, notes: "Duplicada" }), /já possui/);
    stage = "condições crônicas";
    await recordChronicAssessment(context, { medicalRecordId: "prenatal-one", conditionKind: "HYPERTENSION", systolic: 140, diastolic: 90, glucose: null, hba1c: null, riskFactors: ["Histórico familiar"], complications: [], notes: "Acompanhamento da condição previamente diagnosticada." });
    await recordChronicAssessment(context, { medicalRecordId: "prenatal-two", conditionKind: "HYPERTENSION", systolic: 130, diastolic: 80, glucose: null, hba1c: null, riskFactors: [], complications: [], notes: "Acompanhamento longitudinal." });
    assert.equal(await countRows(database, t.healthPatientConditions, and(eq(t.healthPatientConditions.label, "Hipertensão"), isNull(t.healthPatientConditions.endedAt))), 1);
    assert.equal(await countRows(database, t.healthChronicAssessments), 2);
    const chronicHistory = await database.select().from(t.healthChronicAssessments).orderBy(asc(t.healthChronicAssessments.assessedAt));
    assert.deepEqual(chronicHistory[0].riskFactors, ["Histórico familiar"]);
    assert.deepEqual(chronicHistory[1].complications, []);
    stage = "condição longitudinal com revisão anterior/novo e autoria";
    const conditionInput = { medicalRecordId: "prenatal-one", kind: "ALLERGY", label: "Alergia registrada", startedAt: "2020-01-01", endedAt: null, narrative: "História informada e avaliada pelo profissional." };
    const allergy = await savePatientClinicalCondition(context, conditionInput);
    await savePatientClinicalCondition(context, { ...conditionInput, medicalRecordId: "prenatal-two", id: allergy.id, narrative: "Evolução da condição na consulta seguinte." });
    const conditionRevisions = await database.select().from(t.healthPatientConditionRevisions).where(eq(t.healthPatientConditionRevisions.conditionId, allergy.id)).orderBy(asc(t.healthPatientConditionRevisions.createdAt));
    assert.equal(conditionRevisions.length, 2);
    assert.equal(snapshot.narrativeSnapshot.parse(conditionRevisions[1].before).narrative, conditionInput.narrative);
    assert.equal(snapshot.narrativeSnapshot.parse(conditionRevisions[1].after).narrative, "Evolução da condição na consulta seguinte.");
    assert.equal(conditionRevisions[1].medicalRecordId, "prenatal-two");
    stage = "questionário gestacional obrigatório e versionamento das respostas";
    const questionnaireInput = { code: "PRENATAL", name: "Questionário pré-natal", specialtyId: null, conditionKind: "PREGNANCY", required: true, fields: [{ key: "observacao", label: "Observação clínica", type: "TEXT", required: true }, { key: "numero", label: "Valor informado", type: "NUMBER", required: true }] };
    const questionnaireOne = await saveClinicalQuestionnaire(context, questionnaireInput);
    await assert.rejects(assertRequiredClinicalQuestionnaires(database, "prenatal-one"), /questionário obrigatório/);
    await answerClinicalQuestionnaire(context, { medicalRecordId: "prenatal-one", questionnaireId: questionnaireOne.id, answers: { observacao: "Resposta clínica da versão inicial", numero: 0 } });
    await assertRequiredClinicalQuestionnaires(database, "prenatal-one");
    const questionnaireTwo = await saveClinicalQuestionnaire(context, questionnaireInput);
    assert.equal(questionnaireTwo.version, 2);
    await assert.rejects(assertRequiredClinicalQuestionnaires(database, "prenatal-one"), /questionário obrigatório/);
    await answerClinicalQuestionnaire(context, { medicalRecordId: "prenatal-one", questionnaireId: questionnaireTwo.id, answers: { observacao: "Resposta clínica da versão atual", numero: 0 } });
    await assertRequiredClinicalQuestionnaires(database, "prenatal-one");
    assert.equal(await countRows(database, t.healthClinicalQuestionnaireResponses, eq(t.healthClinicalQuestionnaireResponses.medicalRecordId, "prenatal-one")), 2);
    stage = "rastreamento";
    const screening = await saveClinicalScreening(context, { medicalRecordId: "prenatal-one", id: null, kind: "CYTOLOGY", eligible: true, eligibilityReason: "Avaliação clínica registrada", performedAt: null, resultedAt: null, result: null, examRequestId: null, followupNotes: "Acompanhar realização." });
    assert.equal(screening.status, "REQUESTED");
    const resulted = await saveClinicalScreening(context, { medicalRecordId: "prenatal-two", id: screening.id, kind: "CYTOLOGY", eligible: true, eligibilityReason: "Avaliação mantida", performedAt: "2026-01-10", resultedAt: "2026-01-20", result: "Laudo avaliado pelo profissional", examRequestId: null, followupNotes: "Conduta registrada." });
    assert.equal(resulted.status, "RESULTED"); assert.equal(resulted.requestedAt.valueOf(), screening.requestedAt.valueOf());
    stage = "odontologia";
    await database.insert(t.healthSusProcedures).values({ id: "dental-procedure", source: "SIGTAP", sourceBatchId: "fixture", competence: "2026-01", code: "0414020138", description: "Procedimento odontológico" });
    const dental = { medicalRecordId: "care-other", dentition: "ADULT", targetType: "TOOTH", targetCode: "11", surface: "V", condition: "RESTORED", procedureId: "dental-procedure", performed: true, notes: "Evolução e procedimento no dente selecionado." };
    const mark = await recordDentalMark(context, dental);
    assert.ok(mark.performedProcedureId); assert.equal(await countRows(database, t.healthPerformedProcedures), 1);
    await assert.rejects(recordDentalMark(context, { ...dental, dentition: "CHILD" }), /incompatível/);
    assert.equal(await countRows(database, t.healthPerformedProcedures), 1);
    stage = "sessões terapêuticas";
    // The original loose fixture created this FK target later. Keep the same team,
    // now before its first reference under the installed physical constraints.
    await database.insert(t.healthTeams).values({ id: "care-team", name: "Equipe assistencial", unitId: "health-u1" });
    await database.update(t.healthProfessionals).set({ teamId: "care-team" }).where(eq(t.healthProfessionals.id, "health-professional"));
    await database.insert(t.specializedTherapeuticPlans).values({ id: "therapy-plan", patientId: "health-patient", unitId: "health-u1", teamId: "care-team", goals: "Reabilitação", carePlan: "Acompanhamento da equipe", plannedConsultations: 2, createdByUsuarioId: context.user.id });
    await scheduleTherapySessions(context, { medicalRecordId: "care-other", planId: "therapy-plan", specialtyKind: "PHYSIOTHERAPY", dates: ["2026-01-01T12:00:00Z", "2026-02-01T12:00:00Z"] });
    await assert.rejects(scheduleTherapySessions(context, { medicalRecordId: "care-other", planId: "therapy-plan", specialtyKind: "PHYSIOTHERAPY", dates: ["2026-03-01T12:00:00Z"] }), /quantidade prevista/);
    const session = await one(database.select().from(t.healthTherapySessions).orderBy(asc(t.healthTherapySessions.sessionNumber)).limit(1));
    const transition = { medicalRecordId: "care-other", sessionId: session.id, status: "COMPLETED", evolution: "Sessão realizada, evolução registrada." };
    await transitionTherapySession(context, transition); await transitionTherapySession(context, transition);
    assert.equal((await one(database.select().from(t.specializedTherapeuticPlans).where(eq(t.specializedTherapeuticPlans.id, "therapy-plan")).limit(1))).completedConsultations, 1);
    assert.equal(await countRows(database, t.specializedPlanEntries), 1);
    stage = "puerpério e encerramento";
    await closePregnancy(context, { medicalRecordId: "postpartum", pregnancyId: pregnancy.id, outcome: "MISCARRIAGE", reason: "Desfecho informado na consulta", gestationalDaysAtBirth: null, deliveryType: null, deliveryLocation: null, deliveryDate: null, clinicalConditions: "Condições avaliadas e registradas." });
    assert.equal((await one(database.select().from(t.healthPregnancies).where(eq(t.healthPregnancies.id, pregnancy.id)).limit(1))).status, "MISCARRIAGE");
    await assertRequiredClinicalQuestionnaires(database, "care-other");
    assert.equal(await countRows(database, t.healthPregnancyVisits), 2); assert.equal(await countRows(database, t.healthPostpartumVisits), 1);
    await assert.rejects(recordPrenatalVisit(context, { medicalRecordId: "care-other", pregnancyId: pregnancy.id, weight: 60, bloodPressure: null, notes: "Após encerramento" }), /gestação ativa/);
    await assert.rejects(recordDentalMark({ ...context, user: { ...context.user, employeeId: null } }, dental), /profissional autenticado/);
    stage = "XML fiscal com conversão e aprovação de entrada";
    const invoiceInput = { content: pharmacyInvoiceFixture(), warehouseId: "health-warehouse", supplierId: "fornecedor", mappings: [{ sourceKey: "1:0", materialId: "health-product", conversionFactor: 10, batchNumber: "NF-LOTE", productionDate: "2026-01-01", expirationDate: "2030-12-31", manufacturerName: "Fabricante informado" }] };
    await assert.rejects(importPharmacyInvoice(context, { ...invoiceInput, supplierId: "other-health-provider" }), /CNPJ emitente/);
    await assert.rejects(importPharmacyInvoice(context, { ...invoiceInput, mappings: [{ ...invoiceInput.mappings[0], expirationDate: "2031-12-31" }] }), /diferem do XML/);
    const importedInvoice = await importPharmacyInvoice(context, invoiceInput);
    assert.equal(importedInvoice.status, "PENDING_APPROVAL");
    assert.equal(await countRows(database, t.materialStocks, eq(t.materialStocks.batchNumber, "NF-LOTE")), 0);
