      const evidenceStart = exchangeMigration.indexOf("CREATE FUNCTION preserve_health_followup_evidence"), waitlistTableStart = exchangeMigration.indexOf('CREATE TABLE "HealthWaitlistEvent"');
      assert.ok(evidenceStart > 0 && waitlistTableStart > evidenceStart);
      // The full replay retains these PostgreSQL functions/triggers on every run.
      await assert.rejects(database.update(t.healthFollowupBatches).set({ hashSha256: "0".repeat(64) }).where(eq(t.healthFollowupBatches.id, riraBatch.batchIds[0])).catch(rethrowDatabaseGuard), /imutável/);
      await assert.rejects(database.update(t.healthFollowupReceipts).set({ rejected: 0 }).where(eq(t.healthFollowupReceipts.id, partialReceipt.id)).catch(rethrowDatabaseGuard), /imutável/);
