      await assert.rejects(database.update(t.healthWaitlistEvents).set({ notes: "Tentativa de alteração do histórico" }).where(eq(t.healthWaitlistEvents.id, waitingEvidence.id)).catch(rethrowDatabaseGuard), /imutável/);
