    await database.insert(t.medicalRecords).values([{ id: "indicator-record-legacy", patientId: "indicator-patient-unknown", unitId: "indicator-u1", professionalId: "health-professional", date: new Date("2004-05-01T12:00:00Z"), completedAt: new Date("2004-05-01T13:00:00Z") }, { id: "indicator-record-foreign", patientId: "indicator-patient-foreign", unitId: "indicator-u2", professionalId: "health-professional", date: new Date("2005-03-03T12:00:00Z"), completedAt: new Date("2005-03-03T13:00:00Z"), careContextSnapshot: careSnapshot }]);
